transforms.code:

security = value['security']
canCreate = False
canEdit = False
if security['userCRUD'] is not None and security['userId'] is not None:
	if security['userCRUD']['isGatewayAdmin'] or security['userCRUD']['configureMaintenance']['enabled']: 
		canCreate = True
		if len(value['selection']['procedureIds']) > 0 or len(value['selection']['procedureCategoryPaths']) > 0: canEdit = True

return {"canCreate": canCreate, "canDelete": canEdit, "canRead": True, "canUpdate": canEdit}


headers = ["procedureId","procedureName","procedurePath","procedureCategoryId","procedureCategoryName","procedureCategoryPath","enabled", 'iconPath']

rows = []
iconPath = 'material/fact_check'
for row in system.kanoa.utilities.convertDatasetToJSON(value):

	rows.append([row["procedureId"], row["procedureName"], row["procedurePath"], row["procedureCategoryId"], row["procedureCategoryName"], row["procedureCategoryPath"], row["enabled"], iconPath])

iconPath = 'material/folder_open'
for row in system.kanoa.utilities.convertDatasetToJSON(system.kanoa.cmms.getProcedureCategory({})):
	rows.append([None, None, row["procedureCategoryPath"], row["procedureCategoryId"], row["procedureCategoryName"], row["procedureCategoryPath"], row["enabled"], iconPath])

return system.dataset.toDataSet(headers, rows)

config.script:
if view.custom.action.canUpdate:
	if event.column == 'Enabled':
		procedureId = self.props.data.getValueAt(event.row, 'procedureId')
		system.kanoa.cmms..updateprocedureField(procedureId, 'enabled', event.value, self.view.custom.security.userId)
		self.view.refreshBinding("custom.procedures.data")
		self.props.selection.selectedRow = None
	else:
		system.perspective.sendMessage('showFailerToast', 'Column is not enabled for editing.')
else:
	system.perspective.sendMessage('showFailerToast', 'No permissions to update procedures.')

return

