customMethods.script:
system.perspective.print("procedureSelected() called with  %s"%(payload))
procedureIds = []
procedureCategoryPaths = []

for item in payload['selection']:
	if item['value'].has_key('procedureId') and item['value']['procedureId']: procedureIds.append(item['value']['procedureId'])
	elif item['value'].has_key('procedureCategoryId') and item['value']['procedureCategoryId']: procedureCategoryPaths.append(item['value']['procedureCategoryPath'])
	else: procedureCategoryPaths.append(item['value']['path'])

self.view.custom.procedures.selection = {'procedureIds': procedureIds, 'procedureCategoryPaths': procedureCategoryPaths}
return

